                            out[r][c] = 2
                            break

    # Second pass: fill 4s with 2s if they're in a line between 9s
    # Horizontal
    for r in range(h):
        nine_cols = [c for c in range(w) if out[r][c] == 9]
        if len(nine_cols) >= 2:
            for i in range(len(nine_cols) - 1):
                start, end = nine_cols[i], nine_cols[i+1]
                for c in range(start + 1, end):
                    if out[r][c] == 4:
                        out[r][c] = 2

    # Vertical  
    for c in range(w):
        nine_rows = [r for r in range(h) if out[r][c] == 9]
        if len(nine_rows) >= 2:
            for i in range(len(nine_rows) - 1):
                start, end = nine_rows[i], nine_rows[i+1]
                for r in range(start + 1, end):
                    if out[r][c] == 4:
                        out[r][c] = 2

    return out

